  "locations[loc-op-tl-chateau].poneglyph.note": "Dans la salle du trésor du Château de Whole Cake ; estampage volé par Brook pendant la tea party.",
  "locations[loc-op-tl-chateau].poneglyph.inscription": "Une coordonnée vers Laugh Tale (1 sur 4).",
  "locations[loc-op-tl-seducing-woods].localizedName": "Bois de la Séduction",
