  "locations[loc-op-sb-chambord].localizedName": "Île de Chambord",
  "locations[loc-op-sb-chambord].shortDescription": "L'une des îles de l'archipel, lieu de la vente aux enchères des Dragons célestes et théâtre de l'affrontement contre les Pacifistas.",
  "locations[loc-op-mf-justice-tower].localizedName": "Tour de la Justice",
