  "locations[loc-op-fm-gyoverly].localizedName": "Gyoverly Hills",
  "locations[loc-op-fm-gyoverly].shortDescription": "Le quartier aisé de l'île, foyer des hommes-poissons nobles et des marchands les plus riches.",
  "locations[loc-op-fm-mermaid-cove].localizedName": "Crique des Sirènes",
  "locations[loc-op-fm-mermaid-cove].shortDescription": "La crique des sirènes avec le célèbre Mermaid Café, foyer de Camie et des sirènes chanteuses de l'île.",
  "locations[loc-op-fm-noah].localizedName": "Arche Noah",
