  "locations[loc-op-id-entrance].localizedName": "Entrée et portail",
  "locations[loc-op-id-entrance].shortDescription": "L'accès gardé de la prison, surveillé par Hannyabal et Sadi, par lequel Luffy s'infiltre avec les Grands Corsaires.",
  "locations[loc-op-id-l1].localizedName": "Niveau 1 — Enfer écarlate",
