  "locations[loc-op-el-gates].localizedName": "Portes de la Justice",
  "locations[loc-op-el-gates].shortDescription": "Les immenses portes qui s'ouvrent sur le courant menant à Impel Down et Marineford, symbole du pouvoir judiciaire.",
  "locations[loc-op-el-bridge].localizedName": "Pont de l'Hésitation",
