  "locations[loc-op-ws-dock1].localizedName": "Dock n° 1",
  "locations[loc-op-ws-dock1].shortDescription": "Le principal chantier naval de Galley-La, où les meilleurs maîtres charpentiers construisent et réparent les navires.",
  "locations[loc-op-ws-iceburg-mansion].localizedName": "Résidence d'Iceburg",
